  it("moves the current slug, keeps the old one resolving, and announces once", async () => {
    const t = await createTenant("rn-one");
    const seen: TaskflowEventMap["organization.slug_changed"][] = [];
    const off = subscribe("organization.slug_changed", (p) => void seen.push(p));

    const renamed = await renameOrganizationSlug(t.actors.admin, {
      orgId: t.org.id,
      slug: "rn-uno",
    });
    off();

    expect(renamed).toMatchObject({
      id: t.org.id,
      slug: "rn-uno",
      name: t.org.name,
      plan: t.org.plan,
      settings: t.org.settings,
