    expect((await listOrganizationsForUser(t.userIds.owner)).map((o) => o.slug)).toEqual(["rn-uno"]);

    for (const slug of ["rn-one", "rn-uno"]) {
      expect((await resolveOrgBySlug(slug))?.id).toBe(t.org.id);
      expect((await resolveOrgBySlug(slug))?.slug).toBe("rn-uno");
      const actor = await resolveActorForOrg(
        { userId: t.userIds.member, activeOrgId: t.org.id } as never,
        slug,
      );
      expect(actor?.orgId).toBe(t.org.id);
    }

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: t.org.id,
      actorId: t.userIds.admin,
      from: "rn-one",
      to: "rn-uno",
    });

    const audit = await listActivity(t.actors.admin, {
      orgId: t.org.id,
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
