      subjectKind: "organization",
      subjectId: t.org.id,
      metadata: { from: "rn-one", to: "rn-uno" },
    });
  });

  it("is a silent no-op for the current slug", async () => {
    const t = await createTenant("rn-noop");
    const handler = vi.fn();
    const off = subscribe("organization.slug_changed", handler);

    const same = await renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: "rn-noop" });
    off();

    expect(same).toEqual(t.org);
    expect(handler).not.toHaveBeenCalled();
