    expect(back.slug).toBe("ch-b");
    vi.setSystemTime(start + (ORG_SLUG_HOLD_DAYS + 15) * DAY);
    expect((await resolveOrgBySlug("ch-b"))?.id).toBe(t.org.id);
    expect((await resolveOrgBySlug("ch-c"))?.id).toBe(t.org.id);
    vi.setSystemTime(start + 2 * ORG_SLUG_HOLD_DAYS * DAY);
    expect(await resolveOrgBySlug("ch-c")).toBeNull();
    expect((await resolveOrgBySlug("ch-b"))?.id).toBe(t.org.id);
  });
});
